<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { getPlanningTemplate, getPlanningTemplates } from '../data/templates/registry'
import { aggregateMaterials } from '../domain/materials'
import type { DashboardWidget, DashboardWidgetHeight, DashboardWidgetWidth, Room, WorkshopPlan, WorkspaceSettings } from '../domain/types'
import { SqlitePlanRepository } from '../repositories/SqlitePlanRepository'
import { WorkspaceRepository } from '../repositories/WorkspaceRepository'
import { useProjectStore } from '../stores/projectStore'

type CalendarView = 'day' | 'week' | 'month'
type CalendarEvent = { id:string; date:string; type:'plan' | 'todo'; title:string; detail:string; planId?:string; completed?:boolean; startTime?:string; endTime?:string }
type ResizeDrag = { id:string; x:number; y:number; width:number; height:number; initialWidth:DashboardWidgetWidth; initialHeight:DashboardWidgetHeight }
const store = useProjectStore(); const router = useRouter(); const plans = new SqlitePlanRepository(); const workspaceRepository = new WorkspaceRepository()
const newTitle = ref(''); const templateId = ref(''); const buildingId = ref(''); const roomId = ref(''); const importError = ref(''); const workspace = ref<WorkspaceSettings>(); const planDetails = ref<WorkshopPlan[]>([]); const resizeDrag = ref<ResizeDrag>()
const today = new Date().toISOString().slice(0, 10); const nextDay = new Date(Date.now() + 86400000).toISOString().slice(0, 10); const calendarAnchor = ref(today)
const widths:DashboardWidgetWidth[] = ['half', 'wide', 'full']; const heights:DashboardWidgetHeight[] = ['compact', 'standard', 'tall']; const timeSlots = Array.from({ length:12 }, (_, index) => index + 7)
const templates = computed(() => getPlanningTemplates()); const rooms = computed<Room[]>(() => (workspace.value?.rooms ?? []).filter((room) => !buildingId.value || room.buildingId === buildingId.value)); const widgets = computed(() => [...(workspace.value?.dashboard ?? [])].filter((widget) => widget.enabled).sort((a,b) => a.order - b.order))
const allEvents = computed<CalendarEvent[]>(() => [
  ...planDetails.value.flatMap((plan) => plan.days.map((day) => { const entries = plan.schedule.filter((entry) => entry.dayId === day.id); const starts = entries.map((entry) => entry.startTime).filter((time): time is string => Boolean(time)).sort(); const ends = entries.map((entry) => entry.endTime).filter((time): time is string => Boolean(time)).sort(); return { id:`${plan.id}-${day.id}`, date:day.date, type:'plan' as const, title:plan.metadata.title, detail:[day.title, plan.metadata.location].filter(Boolean).join(' · '), planId:plan.id, startTime:day.startTime ?? starts[0], endTime:day.endTime ?? ends.at(-1) } })),
  ...(workspace.value?.todos ?? []).filter((todo) => todo.dueDate).map((todo) => ({ id:todo.id, date:todo.dueDate!, type:'todo' as const, title:todo.title, detail:'', completed:todo.completed })),
])
const upcomingPlans = computed(() => allEvents.value.filter((event) => event.type === 'plan' && event.date >= today).sort((a,b) => a.date.localeCompare(b.date))); const upcomingTodos = computed(() => allEvents.value.filter((event) => event.type === 'todo' && !event.completed && event.date >= today).sort((a,b) => a.date.localeCompare(b.date)))
const nextDayMaterials = computed(() => { const grouped = new Map<string, { name:string; quantity:string[]; plans:string[] }>(); for (const plan of planDetails.value.filter((item) => item.days.some((day) => day.date === nextDay))) for (const item of aggregateMaterials(plan.materials, plan.schedule)) { const current = grouped.get(item.material.name) ?? { name:item.material.name, quantity:[], plans:[] }; if (item.material.quantity) current.quantity.push(item.material.quantity); current.plans.push(plan.metadata.title); grouped.set(item.material.name, current) }; return [...grouped.values()] })
function asDate(date:string):Date { return new Date(`${date}T12:00:00`) }; function key(date:Date):string { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}` }; function addDays(date:string, amount:number):string { const result = asDate(date); result.setDate(result.getDate()+amount); return key(result) }; function weekStart(date:string):string { const result = asDate(date); result.setDate(result.getDate()-((result.getDay()+6)%7)); return key(result) }
function calendarDays(view:CalendarView):string[] { if (view === 'day') return [calendarAnchor.value]; if (view === 'week') return Array.from({ length:7 }, (_, index) => addDays(weekStart(calendarAnchor.value), index)); const anchor = asDate(calendarAnchor.value); const first = new Date(anchor.getFullYear(), anchor.getMonth(), 1); const mondayOffset = (first.getDay()+6)%7; return Array.from({ length:42 }, (_, index) => key(new Date(first.getFullYear(), first.getMonth(), 1-mondayOffset+index))) }
function calendarLabel(view:CalendarView):string { const date = asDate(calendarAnchor.value); if (view === 'day') return date.toLocaleDateString('de-DE', { weekday:'long', day:'numeric', month:'long' }); if (view === 'week') { const days = calendarDays('week'); return `${shortDate(days[0])} – ${shortDate(days[6])}` }; return date.toLocaleDateString('de-DE', { month:'long', year:'numeric' }) }
function moveCalendar(view:CalendarView, direction:-1|1):void { if (view === 'month') { const date = asDate(calendarAnchor.value); date.setMonth(date.getMonth()+direction); calendarAnchor.value = key(date) } else calendarAnchor.value = addDays(calendarAnchor.value, view === 'week' ? direction*7 : direction) }
function formatDate(date:string):string { return asDate(date).toLocaleDateString('de-DE', { weekday:'short', day:'2-digit', month:'2-digit' }) }; function shortDate(date:string):string { return asDate(date).toLocaleDateString('de-DE', { day:'2-digit', month:'short' }) }; function dayNumber(date:string):string { return String(asDate(date).getDate()) }; function weekday(date:string):string { return asDate(date).toLocaleDateString('de-DE', { weekday:'short' }).replace('.','') }
function eventsFor(date:string):CalendarEvent[] { return allEvents.value.filter((event) => event.date === date) }; function allDayEvents(date:string):CalendarEvent[] { return eventsFor(date).filter((event) => !event.startTime) }; function timedEvents(date:string):CalendarEvent[] { return eventsFor(date).filter((event) => Boolean(event.startTime)) }; function toMinutes(time?:string):number { const [hour, minute] = (time ?? '07:00').split(':').map(Number); return hour*60+minute }
function eventStyle(event:CalendarEvent):Record<string,string> { const start = Math.max(420, Math.min(1140, toMinutes(event.startTime))); const end = Math.max(start+30, Math.min(1140, toMinutes(event.endTime || event.startTime)+60)); return { top:`${((start-420)/720)*100}%`, height:`${Math.max(5, ((end-start)/720)*100)}%` } }; function eventTime(event:CalendarEvent):string { return event.startTime ? `${event.startTime}${event.endTime ? ` – ${event.endTime}` : ''}` : 'Ganztägig' }; function openEvent(event:CalendarEvent):void { if (event.type === 'plan' && event.planId) void open(event.planId); else void router.push({ name:'workspace-settings' }) }
function steps(distance:number, pixels:number):number { return distance < 0 ? Math.ceil(distance/pixels) : Math.floor(distance/pixels) }; function clamp(index:number, length:number):number { return Math.max(0, Math.min(length-1, index)) }
function beginResize(widget:DashboardWidget, event:PointerEvent):void { event.preventDefault(); const handle = event.currentTarget as HTMLElement; handle.setPointerCapture(event.pointerId); resizeDrag.value = { id:widget.id, x:event.clientX, y:event.clientY, width:widths.indexOf(widget.width), height:heights.indexOf(widget.height), initialWidth:widget.width, initialHeight:widget.height } }
function resize(widget:DashboardWidget, event:PointerEvent):void { const drag = resizeDrag.value; if (!drag || drag.id !== widget.id) return; widget.width = widths[clamp(drag.width+steps(event.clientX-drag.x,72), widths.length)]; widget.height = heights[clamp(drag.height+steps(event.clientY-drag.y,58), heights.length)] }
async function finishResize(widget:DashboardWidget, event:PointerEvent):Promise<void> { const drag = resizeDrag.value; if (!drag || drag.id !== widget.id) return; const handle = event.currentTarget as HTMLElement; if (handle.hasPointerCapture(event.pointerId)) handle.releasePointerCapture(event.pointerId); resizeDrag.value = undefined; if (widget.width === drag.initialWidth && widget.height === drag.initialHeight) return; try { workspace.value = await workspaceRepository.save(workspace.value!) } catch (cause) { importError.value = cause instanceof Error ? cause.message : 'Widget-Größe konnte nicht gespeichert werden.' } }
function cancelResize(widget:DashboardWidget, event:PointerEvent):void { const drag = resizeDrag.value; if (!drag || drag.id !== widget.id) return; widget.width = drag.initialWidth; widget.height = drag.initialHeight; resizeDrag.value = undefined }
async function refresh():Promise<void> { await store.refresh(); planDetails.value = (await Promise.all(store.plans.map((plan) => plans.get(plan.id)))).filter((plan):plan is WorkshopPlan => Boolean(plan)) }; onMounted(async () => { try { await Promise.all([refresh(), workspaceRepository.get().then((settings) => { workspace.value = settings })]) } catch (cause) { importError.value = cause instanceof Error ? cause.message : 'Dashboard konnte nicht geladen werden.' } })
async function create():Promise<void> { const room = workspace.value?.rooms.find((item) => item.id === roomId.value); const building = workspace.value?.buildings.find((item) => item.id === (room?.buildingId ?? buildingId.value)); const location = room ? { buildingId:room.buildingId, roomId:room.id, label:`${building?.name ?? ''} · ${room.name}` } : building ? { buildingId:building.id, label:building.name } : undefined; const plan = await store.create(newTitle.value || 'Neue Planung', getPlanningTemplate(templateId.value), location); await router.push({ name:'editor', params:{ id:plan.id } }) }; async function open(id:string):Promise<void> { await router.push({ name:'editor', params:{ id } }) }; async function loadJenaChatSample():Promise<void> { try { const plan = await store.loadJenaChatSample(); await open(plan.id) } catch (cause) { importError.value = cause instanceof Error ? cause.message : 'JenaChat-Sample konnte nicht geladen werden.' } }; async function importProject(event:Event):Promise<void> { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; try { const plan = await store.importProject(JSON.parse(await file.text())); await open(plan.id) } catch (cause) { importError.value = cause instanceof Error ? cause.message : 'Import fehlgeschlagen.' } }
</script>

<template><main class="home-shell"><header class="home-header"><div><p class="eyebrow">Verlaufsplaner · lokaler Arbeitsbereich</p><h1>Mein Dashboard</h1><p>Planungen, Aufgaben und Materialvorbereitung auf einen Blick.</p></div><form class="new-plan dashboard-new-plan" @submit.prevent="create"><input v-model="newTitle" placeholder="Titel der neuen Planung" aria-label="Titel der neuen Planung"><label>Vorlage<select v-model="templateId"><option value="">Ohne Vorlage</option><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.name.de }}</option></select></label><label>Gebäude<select v-model="buildingId" @change="roomId = ''"><option value="">Kein Gebäude</option><option v-for="building in workspace?.buildings" :key="building.id" :value="building.id">{{ building.name }}</option></select></label><label>Raum<select v-model="roomId" :disabled="!buildingId"><option value="">Kein Raum</option><option v-for="room in rooms" :key="room.id" :value="room.id">{{ room.name }}</option></select></label><button type="submit">Neue Planung</button></form><button type="button" class="settings-trigger" aria-label="Einstellungen öffnen" title="Einstellungen" @click="router.push({ name:'workspace-settings' })">⚙</button></header><section class="home-tools"><label class="file-label">JSON importieren<input type="file" accept="application/json,.json" @change="importProject"></label><button type="button" class="secondary" @click="loadJenaChatSample">JenaChat-Sample laden</button><p v-if="store.migrationNotice" class="success-message">{{ store.migrationNotice }}</p><p v-if="importError" class="error-message">{{ importError }}</p></section>
<section class="dashboard-grid"><article v-for="widget in widgets" :key="widget.id" class="dashboard-widget" :class="[`widget-${widget.id}`, `widget-width-${widget.width}`, `widget-height-${widget.height}`, { resizing:resizeDrag?.id === widget.id }]">
<template v-if="widget.id === 'calendar'"><div class="widget-heading calendar-heading"><div><p class="eyebrow">{{ widget.calendarView === 'day' ? 'Tagesansicht' : widget.calendarView === 'month' ? 'Monatsansicht' : 'Wochenansicht' }}</p><h2>{{ calendarLabel(widget.calendarView ?? 'week') }}</h2></div><div class="calendar-actions"><button type="button" class="secondary nav" aria-label="Vorheriger Zeitraum" @click="moveCalendar(widget.calendarView ?? 'week', -1)">‹</button><button type="button" class="secondary" @click="calendarAnchor = today">Heute</button><button type="button" class="secondary nav" aria-label="Nächster Zeitraum" @click="moveCalendar(widget.calendarView ?? 'week', 1)">›</button><button type="button" class="secondary" title="Kalenderansicht einstellen" @click="router.push({ name:'workspace-settings' })">⚙</button></div></div>
<div v-if="widget.calendarView === 'month'" class="month-grid"><span v-for="name in ['Mo','Di','Mi','Do','Fr','Sa','So']" :key="name" class="weekday">{{ name }}</span><section v-for="date in calendarDays('month')" :key="date" class="month-day" :class="{ muted:date.slice(0,7) !== calendarAnchor.slice(0,7), today:date === today }"><strong>{{ dayNumber(date) }}</strong><button v-for="event in eventsFor(date)" :key="event.id" type="button" class="month-event" :class="event.type" @click="openEvent(event)"><span v-if="event.startTime">{{ event.startTime }}</span>{{ event.title }}</button></section></div>
<div v-else class="time-scroll"><div class="time-grid" :style="{ gridTemplateColumns:`52px repeat(${calendarDays(widget.calendarView ?? 'week').length}, minmax(138px, 1fr))` }"><div class="time-axis"><span>Zeit</span><span v-for="hour in timeSlots" :key="hour">{{ String(hour).padStart(2,'0') }}:00</span></div><section v-for="date in calendarDays(widget.calendarView ?? 'week')" :key="date" class="time-day" :class="{ today:date === today }"><header><small>{{ weekday(date) }}</small><strong>{{ dayNumber(date) }}</strong></header><div class="all-day"><button v-for="event in allDayEvents(date)" :key="event.id" type="button" class="all-day-event" :class="event.type" @click="openEvent(event)">{{ event.title }}</button></div><div class="slots"><button v-for="event in timedEvents(date)" :key="event.id" type="button" class="timed-event" :style="eventStyle(event)" @click="openEvent(event)"><strong>{{ event.title }}</strong><small>{{ eventTime(event) }}</small></button></div></section></div></div></template>
<template v-else-if="widget.id === 'upcoming-plans'"><div class="widget-heading"><div><p class="eyebrow">Planungen</p><h2>Nächste Verlaufspläne</h2></div><span>{{ widget.limit ?? 5 }}</span></div><ol class="dashboard-list"><li v-for="event in upcomingPlans.slice(0, widget.limit ?? 5)" :key="event.id"><button type="button" @click="openEvent(event)"><strong>{{ event.title }}</strong><small>{{ formatDate(event.date) }}{{ event.detail ? ` · ${event.detail}` : '' }}</small></button></li><li v-if="!upcomingPlans.length" class="empty-state">Keine kommenden Planungen.</li></ol></template>
<template v-else-if="widget.id === 'upcoming-todos'"><div class="widget-heading"><div><p class="eyebrow">Aufgaben</p><h2>Nächste Todos</h2></div><span>{{ widget.limit ?? 5 }}</span></div><ol class="dashboard-list"><li v-for="event in upcomingTodos.slice(0, widget.limit ?? 5)" :key="event.id"><button type="button" @click="router.push({ name:'workspace-settings' })"><strong>{{ event.title }}</strong><small>{{ formatDate(event.date) }}</small></button></li><li v-if="!upcomingTodos.length" class="empty-state">Keine offenen Aufgaben mit Termin.</li></ol></template>
<template v-else><div class="widget-heading"><div><p class="eyebrow">Vorbereitung</p><h2>Materialien für morgen</h2></div><span>{{ formatDate(nextDay) }}</span></div><p v-if="!nextDayMaterials.length" class="empty-state">Für morgen sind keine Planmaterialien hinterlegt.</p><ul v-else class="material-prep-list"><li v-for="material in nextDayMaterials" :key="material.name"><strong>{{ material.name }}</strong><span>{{ material.quantity.join(', ') || 'Menge offen' }}</span><small>{{ [...new Set(material.plans)].join(', ') }}</small></li></ul><RouterLink class="secondary link-button" :to="{ name:'workspace-settings' }">Bestand vorbereiten</RouterLink></template>
<button type="button" class="resize-handle" :aria-label="`${widget.id} in Rastergröße ändern`" title="Zum Ändern von Breite und Höhe ziehen" @pointerdown="beginResize(widget, $event)" @pointermove="resize(widget, $event)" @pointerup="finishResize(widget, $event)" @pointercancel="cancelResize(widget, $event)">&#x2198;</button></article></section>
<section v-if="store.plans.length" class="project-grid"><article v-for="plan in store.plans" :key="plan.id" class="project-card"><p class="eyebrow">{{ plan.dateRange || 'Ohne Termin' }}</p><h2>{{ plan.title }}</h2><p>Zuletzt bearbeitet: {{ new Date(plan.updatedAt).toLocaleString('de-DE') }}</p><div><button type="button" @click="open(plan.id)">Öffnen</button><button type="button" class="secondary" @click="store.duplicate(plan.id).then((copy) => open(copy.id))">Duplizieren</button><button type="button" class="danger" @click="store.remove(plan.id).then(refresh)">Löschen</button></div></article></section><section v-else class="home-empty"><h2>Die erste Planung beginnt hier.</h2><p>Erstellen Sie eine Planung oder ergänzen Sie Gebäude, Bestände und Aufgaben unter Arbeitsbereich.</p></section></main></template>

<style scoped>
.dashboard-widget{position:relative}.dashboard-widget.resizing{user-select:none;outline:2px solid #397078;outline-offset:2px}.resize-handle{position:absolute;right:.35rem;bottom:.35rem;z-index:6;width:28px;height:28px;padding:0;display:grid;place-items:center;border:1px solid #b8cacc;border-radius:5px;color:#397078;background:#f7fbfb;cursor:nwse-resize;touch-action:none}.calendar-heading{align-items:center}.calendar-actions{display:flex;gap:.25rem}.calendar-actions button{padding:.32rem .48rem}.calendar-actions .nav{min-width:2rem;font-size:1.25rem;line-height:1}.month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));min-width:560px;overflow:hidden;border:1px solid #d4dfe1;border-radius:7px}.weekday{padding:.4rem;background:#eef4f4;border-bottom:1px solid #d4dfe1;color:#587078;font-size:.75rem;font-weight:800;text-align:center}.month-day{min-height:92px;padding:.35rem;overflow:hidden;border-right:1px solid #e0e8e9;border-bottom:1px solid #e0e8e9}.month-day>strong{display:block;width:1.6rem;height:1.6rem;padding-top:.18rem;border-radius:50%;text-align:center;font-size:.8rem}.today>strong{color:#fff;background:#1d777f}.muted{background:#f7f9f9;color:#94a4a8}.month-event,.all-day-event,.timed-event{display:block;width:100%;overflow:hidden;border:0;border-radius:3px;text-align:left;text-overflow:ellipsis;white-space:nowrap;font-size:.72rem;margin-top:.2rem;padding:.17rem .3rem;color:#124f57;background:#dbeff1}.month-event.todo,.all-day-event.todo{color:#734d19;background:#f8e8c9}.month-event span{margin-right:.2rem;font-weight:800}.time-scroll{overflow:auto;border:1px solid #d4dfe1;border-radius:7px}.time-grid{display:grid;min-width:340px;background:#fff}.time-axis,.time-day{display:grid;grid-template-rows:48px auto minmax(672px,1fr);min-width:0}.time-axis{color:#64787d;font-size:.7rem;border-right:1px solid #dce5e6}.time-axis>span:first-child{display:grid;place-items:center;background:#eef4f4;font-weight:800}.time-axis>span:not(:first-child){height:56px;padding:.25rem .35rem;border-top:1px solid #e1e9ea;text-align:right}.time-day{border-right:1px solid #dce5e6}.time-day header{display:flex;justify-content:center;align-items:center;gap:.35rem;background:#eef4f4;border-bottom:1px solid #d4dfe1;text-transform:uppercase;font-size:.72rem}.time-day header strong{display:grid;place-items:center;width:1.65rem;height:1.65rem;border-radius:50%;font-size:.86rem}.all-day{min-height:28px;padding:.12rem;border-bottom:1px solid #dce5e6}.slots{position:relative;min-height:672px;background:repeating-linear-gradient(to bottom,transparent 0,transparent 55px,#e1e9ea 56px)}.timed-event{position:absolute;z-index:1;left:.18rem;right:.18rem;width:auto;min-height:32px;white-space:normal;color:#fff;background:#1d777f;box-shadow:0 1px 2px #16383c2b}.timed-event strong,.timed-event small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.timed-event small{margin-top:.1rem;opacity:.9}@media(max-width:760px){.calendar-heading{align-items:stretch;flex-direction:column}.calendar-actions{justify-content:flex-end}.month-grid{min-width:510px}.month-day{min-height:78px}}
</style>
